constexpr char TaskHpp[] = R"(/**
 * @file task.hpp
 * @brief The @NAME@ task: a point in a plane moves to a target.
 * @details Generated by ppokit-new as a starting point. Replace the physics, the
 * observation and the rewards with your own, and keep task.json in step: the layout
 * header @NAME@_layout.hpp (sizes, channel and scenario names) is generated from it.
 *
 * The members after Step are optional; each one turns on a feature of `train`:
 * Configure (curriculum), Succeeded (promotion), LastRewardChannels (reward curves per
 * channel), RewardWeights / SetRewardWeights (weights changed live from the studio).
 */
#pragma once

#include "@NAME@_layout.hpp"

#include "ppokit/runtime/collector.hpp"

#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <random>
#include <stdexcept>
#include <string>
#include <vector>

namespace @NAME@_example {

using Layout = TaskLayout;
inline constexpr std::size_t ObservationSize = Layout::Observation::Size;
inline constexpr std::size_t ActionSize = Layout::Action::Size;
using Observation = std::array<float, ObservationSize>;
using Action = std::array<float, ActionSize>;
using Channel = Layout::Reward::Channel;

/** @brief A point starts at the origin and must reach a target within StepLimit steps. */
class @TYPE@Task final
{
public:
    /** @brief Distance covered by a full action in one step. */
    static constexpr double StepScale = 0.1;
    /** @brief The target is reached within this distance. */
    static constexpr double GoalRadius = 0.1;
    static constexpr int StepLimit = 40;
    /** @brief Raw Time channel of every step. */
    static constexpr double StepCost = -0.01;
    /** @brief Raw Goal channel of the step that reaches the target. */
    static constexpr double GoalBonus = 1.0;
    /** @brief Start distance without curriculum: the task.json "default". */
    static constexpr double DefaultStartDistance = 0.5;

    explicit @TYPE@Task(std::uint32_t seed) : rng_(seed), weights_(Layout::Reward::DefaultWeights)
    {
        scenario_.startDistance = DefaultStartDistance;
    }

    /** @brief Starts an episode: the target at the scenario's distance, in a random direction. */
    Observation Reset()
    {
        constexpr double Pi = 3.14159265358979323846;
        double const angle = std::uniform_real_distribution<double>(0.0, 2.0 * Pi)(rng_);
        targetX_ = scenario_.startDistance * std::cos(angle);
        targetY_ = scenario_.startDistance * std::sin(angle);
        x_ = 0.0;
        y_ = 0.0;
        steps_ = 0;
        reached_ = false;
        channels_.fill(0.0);
        return Observe();
    }

    /** @brief Moves by the clipped action; terminates at the target, truncates at StepLimit. */
    ppokit::runtime::StepOutcome<double> Step(Action const& action, Observation& next)
    {
        double const before = Distance();
        x_ += StepScale * std::clamp(static_cast<double>(action[0]), -1.0, 1.0);
        y_ += StepScale * std::clamp(static_cast<double>(action[1]), -1.0, 1.0);
        ++steps_;
        double const after = Distance();
        reached_ = after <= GoalRadius;

        SetChannel(Channel::Progress, before - after);
        SetChannel(Channel::Time, StepCost);
        SetChannel(Channel::Goal, reached_ ? GoalBonus : 0.0);
        double reward = 0.0;
        for (double const value : channels_)
        {
            reward += value;
        }

        next = Observe();
        if (reached_)
        {
            return {reward, ppokit::runtime::StepEnd::Terminated};
        }
        if (steps_ == StepLimit)
        {
            return {reward, ppokit::runtime::StepEnd::Truncated};
        }
        return {reward, ppokit::runtime::StepEnd::Running};
    }

    /** @brief Scenario of the next episodes, values in task.json "scenario" order. */
    void Configure(std::vector<double> const& scenario) { scenario_ = Layout::Scenario::From(scenario); }

    /** @brief Whether the episode that just ended reached the target. */
    bool Succeeded() const noexcept { return reached_; }

    /** @brief Weighted value of every reward channel for the last step, in task.json order. */
    double const* LastRewardChannels() const noexcept { return channels_.data(); }

    std::vector<double> RewardWeights() const { return {weights_.begin(), weights_.end()}; }

    /** @throws std::invalid_argument for a wrong count or a non-finite weight; nothing changes then. */
    void SetRewardWeights(std::vector<double> const& weights)
    {
        if (weights.size() != weights_.size())
        {
            throw std::invalid_argument(std::to_string(weights_.size()) + " weights expected");
        }
        for (double const weight : weights)
        {
            if (!std::isfinite(weight))
            {
                throw std::invalid_argument("weights must be finite numbers");
            }
        }
        std::copy(weights.begin(), weights.end(), weights_.begin());
    }

private:
    void SetChannel(Channel channel, double raw) noexcept
    {
        auto const index = static_cast<std::size_t>(channel);
        channels_[index] = weights_[index] * raw;
    }

    double Distance() const noexcept { return std::hypot(targetX_ - x_, targetY_ - y_); }

    Observation Observe() const noexcept
    {
        Observation observation{};
        observation[Layout::Observation::Target::Offset] = static_cast<float>(targetX_ - x_);
        observation[Layout::Observation::Target::Offset + 1] = static_cast<float>(targetY_ - y_);
        observation[Layout::Observation::Clock::Offset] = static_cast<float>(steps_) / static_cast<float>(StepLimit);
        return observation;
    }

    std::mt19937 rng_;
    std::array<double, Layout::Reward::Count> weights_;
    std::array<double, Layout::Reward::Count> channels_{};
    Layout::Scenario scenario_{};
    double x_ = 0.0;
    double y_ = 0.0;
    double targetX_ = 0.0;
    double targetY_ = 0.0;
    int steps_ = 0;
    bool reached_ = false;
};

/** @brief The task of a seed, for training and evaluation. */
inline @TYPE@Task MakeTask(std::uint32_t seed)
{
    return @TYPE@Task(seed);
}

} // namespace @NAME@_example
)";

constexpr char EnvironmentCpp[] = R"(/**
 * @file environment.cpp
 * @brief @NAME@ simulation adapter for the common ppokit-run learner.
 */
#include "task.hpp"

#include "ppokit/environment/sdk.hpp"

#include <nlohmann/json.hpp>

#include <algorithm>
#include <filesystem>
#include <random>
#include <vector>

namespace {
using namespace @NAME@_example;

class @TYPE@Environment final
{
public:
    static constexpr std::size_t MetricCount = 1;

    @TYPE@Environment(std::filesystem::path const& /*project*/, std::uint64_t seed)
        : task_(static_cast<std::uint32_t>(seed)), scenarioRng_(static_cast<std::uint32_t>(seed ^ 0x9e3779b9U))
    {
    }

    /** @brief Start an episode and publish its first observation. */
    void Reset(float* observation, float* /*world*/)
    {
        task_.Configure({std::uniform_real_distribution<double>(minimumDistance_, maximumDistance_)(scenarioRng_)});
        Observation const value = task_.Reset();
        std::copy(value.begin(), value.end(), observation);
    }

    /** @brief Report the stage promotion metric declared by task.json. */
    void EpisodeMetrics(double* metrics) const { metrics[0] = task_.Succeeded() ? 1.0 : 0.0; }

    /** @brief Apply the distance range selected by PPOKit's common curriculum. */
    void ApplyCurriculumStage(std::string const& name, std::string const& payload)
    {
        auto const stage = nlohmann::json::parse(payload);
        if (!stage.contains("start_distance") || !stage.at("start_distance").is_array()
            || stage.at("start_distance").size() != 2)
            throw std::invalid_argument("curriculum stage '" + name + "' requires start_distance [min,max]");
        double const minimum = stage.at("start_distance").at(0).get<double>();
        double const maximum = stage.at("start_distance").at(1).get<double>();
        if (!std::isfinite(minimum) || !std::isfinite(maximum) || minimum <= 0.0 || minimum > maximum)
            throw std::invalid_argument("curriculum stage '" + name + "' has an invalid distance range");
        minimumDistance_ = minimum;
        maximumDistance_ = maximum;
    }

    /** @brief Apply one action through the task without owning any PPO logic. */
    ppokit::runtime::StepEnd Step(float const* action, float* observation, float* /*world*/,
        double* rewardChannels)
    {
        Action applied{};
        std::copy_n(action, applied.size(), applied.begin());
        Observation next{};
        auto const outcome = task_.Step(applied, next);
        std::copy(next.begin(), next.end(), observation);
        std::copy_n(task_.LastRewardChannels(), Layout::Reward::Count, rewardChannels);
        return outcome.end;
    }

    /** @brief Apply task.json reward-channel weights. */
    void SetWeights(double const* weights)
    {
        task_.SetRewardWeights(std::vector<double>(weights, weights + Layout::Reward::Count));
    }

    /** @brief Return task.json reward-channel weights. */
    void Weights(double* weights) const
    {
        std::vector<double> const values = task_.RewardWeights();
        std::copy(values.begin(), values.end(), weights);
    }

private:
    @TYPE@Task task_;
    std::mt19937 scenarioRng_;
    double minimumDistance_ = @TYPE@Task::DefaultStartDistance;
    double maximumDistance_ = @TYPE@Task::DefaultStartDistance;
};
} // namespace

PPOKIT_ENVIRONMENT(@TYPE@Environment, "@NAME@", ObservationSize, ActionSize, Layout::Reward::Count, 0)
)";

